def configure_gsl_stats_median(gsl):
    gsl.gsl_stats_median_from_sorted_data.argtypes = [ctypes.POINTER(ctypes.c_double), ctypes.c_size_t]
    gsl.gsl_stats_median_from_sorted_data.restype = ctypes.c_double

def compute_median(sorted_data):
    gsl = load_gsl_libraries()
    configure_gsl_stats_median(gsl)

    data_ptr = ctypes.cast(sorted_data, ctypes.POINTER(ctypes.c_double))
    median = gsl.gsl_stats_median_from_sorted_data(data_ptr, len(sorted_data))
    return float(median)

